// Demonstrating classes and objects

// Define a class (blueprint)
class Student {
    // Attributes (data members)
    String name;
    int age;
    double gpa;
    String major;

    // Constructor - special method that initializes objects
    public Student(String studentName, int studentAge, double studentGPA, String studentMajor) {
        name = studentName;
        age = studentAge;
        gpa = studentGPA;
        major = studentMajor;
    }

    // Default constructor
    public Student() {
        name = "Unknown";
        age = 0;
        gpa = 0.0;
        major = "Undeclared";
    }

    // Methods (behaviors)
    public void displayInfo() {
        System.out.println("Student Information:");
        System.out.println("  Name: " + name);
        System.out.println("  Age: " + age);
        System.out.println("  GPA: " + gpa);
        System.out.println("  Major: " + major);
    }

    public void study() {
        System.out.println(name + " is studying " + major);
    }

    public void takeExam(String subject) {
        System.out.println(name + " is taking an exam in " + subject);
    }

    // Method with return value
    public boolean isHonorStudent() {
        return gpa >= 3.5;
    }

    // Method to update GPA
    public void updateGPA(double newGPA) {
        if (newGPA >= 0.0 && newGPA <= 4.0) {
            gpa = newGPA;
            System.out.println(name + "'s GPA updated to: " + gpa);
        } else {
            System.out.println("Invalid GPA! Must be between 0.0 and 4.0");
        }
    }
}

// Another class example
class BankAccount {
    String accountNumber;
    String accountHolder;
    double balance;

    public BankAccount(String accNumber, String holder, double initialBalance) {
        accountNumber = accNumber;
        accountHolder = holder;
        balance = initialBalance;
    }

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            System.out.println("Deposited: $" + amount);
            System.out.println("New balance: $" + balance);
        } else {
            System.out.println("Deposit amount must be positive!");
        }
    }

    public void withdraw(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
            System.out.println("Withdrawn: $" + amount);
            System.out.println("New balance: $" + balance);
        } else if (amount > balance) {
            System.out.println("Insufficient funds!");
        } else {
            System.out.println("Withdrawal amount must be positive!");
        }
    }

    public void displayBalance() {
        System.out.println(accountHolder + "'s balance: $" + balance);
    }
}

// Main class to demonstrate objects
public class ClassesObjectsDemo {
    public static void main(String[] args) {
        System.out.println("=== Classes and Objects Demonstration ===\n");

        // Creating objects (instances of Student class)
        Student student1 = new Student("Alice Johnson", 20, 3.8, "Computer Science");
        Student student2 = new Student("Bob Smith", 22, 3.2, "Mathematics");
        Student student3 = new Student();  // Using default constructor

        // Using object methods
        System.out.println("=== Student Objects ===");
        student1.displayInfo();
        student1.study();
        student1.takeExam("Data Structures");
        System.out.println("Is honor student? " + student1.isHonorStudent());

        System.out.println("\n---");
        student2.displayInfo();
        student2.study();
        System.out.println("Is honor student? " + student2.isHonorStudent());

        System.out.println("\n---");
        student3.displayInfo();

        // Modifying object attributes
        System.out.println("\n=== Modifying Objects ===");
        student3.name = "Charlie Brown";
        student3.age = 19;
        student3.updateGPA(3.6);
        student3.major = "Physics";
        student3.displayInfo();

        // Bank Account example
        System.out.println("\n=== Bank Account Example ===");
        BankAccount account1 = new BankAccount("ACC123456", "Alice Johnson", 1000.0);
        BankAccount account2 = new BankAccount("ACC789012", "Bob Smith", 500.0);

        account1.displayBalance();
        account1.deposit(250.0);
        account1.withdraw(100.0);
        account1.withdraw(2000.0);  // Should fail

        System.out.println("\n---");
        account2.displayBalance();
        account2.deposit(100.0);

        // Array of objects
        System.out.println("\n=== Array of Objects ===");
        Student[] students = new Student[3];
        students[0] = new Student("Diana Prince", 21, 3.9, "Engineering");
        students[1] = new Student("Bruce Wayne", 23, 3.4, "Business");
        students[2] = new Student("Clark Kent", 22, 3.7, "Journalism");

        System.out.println("Student Roster:");
        for (Student student : students) {
            student.displayInfo();
            System.out.println();
        }

        // Finding honor students
        System.out.println("Honor Students:");
        for (Student student : students) {
            if (student.isHonorStudent()) {
                System.out.println("  - " + student.name + " (GPA: " + student.gpa + ")");
            }
        }

        // Object comparison
        System.out.println("\n=== Object Comparison ===");
        Student s1 = new Student("John Doe", 20, 3.5, "CS");
        Student s2 = new Student("John Doe", 20, 3.5, "CS");

        System.out.println("s1 == s2: " + (s1 == s2));  // false (different objects)
        System.out.println("s1.name.equals(s2.name): " + s1.name.equals(s2.name));  // true

        // Null objects
        System.out.println("\n=== Null Objects ===");
        Student nullStudent = null;
        // nullStudent.displayInfo();  // This would cause NullPointerException

        if (nullStudent != null) {
            nullStudent.displayInfo();
        } else {
            System.out.println("Student object is null!");
        }
    }
}

// Demonstrating constructors

class Person {
    // Attributes
    String name;
    int age;
    String email;

    // Default constructor (no parameters)
    public Person() {
        name = "Unknown";
        age = 0;
        email = "not provided";
        System.out.println("Default constructor called - Person created with default values");
    }

    // Parameterized constructor
    public Person(String personName, int personAge) {
        name = personName;
        age = personAge;
        email = "not provided";
        System.out.println("Parameterized constructor (name, age) called");
    }

    // Another parameterized constructor
    public Person(String personName, int personAge, String personEmail) {
        name = personName;
        age = personAge;
        email = personEmail;
        System.out.println("Parameterized constructor (name, age, email) called");
    }

    // Copy constructor - creates new object from existing object
    public Person(Person original) {
        this.name = original.name;
        this.age = original.age;
        this.email = original.email;
        System.out.println("Copy constructor called - created copy of " + original.name);
    }

    // Method to display information
    public void displayInfo() {
        System.out.println("Name: " + name);
        System.out.println("Age: " + age);
        System.out.println("Email: " + email);
        System.out.println();
    }
}

class Car {
    String make;
    String model;
    int year;
    double price;
    int mileage;

    // Constructor with validation
    public Car(String carMake, String carModel, int carYear, double carPrice) {
        if (carYear < 1886 || carYear > 2024) {
            System.out.println("Invalid year! Setting to 2024");
            year = 2024;
        } else {
            year = carYear;
        }

        if (carPrice < 0) {
            System.out.println("Price cannot be negative! Setting to 0");
            price = 0;
        } else {
            price = carPrice;
        }

        make = carMake;
        model = carModel;
        mileage = 0;  // Default value for new car

        System.out.println("New car created: " + year + " " + make + " " + model);
    }

    // Constructor chaining - calling another constructor
    public Car(String carMake, String carModel) {
        this(carMake, carModel, 2024, 0.0);  // Calls the main constructor
        System.out.println("Chained constructor called");
    }

    // Default constructor with chaining
    public Car() {
        this("Unknown", "Unknown", 2024, 0.0);
        System.out.println("Default car constructor called");
    }

    public void displayCarInfo() {
        System.out.println(year + " " + make + " " + model);
        System.out.println("Price: $" + price);
        System.out.println("Mileage: " + mileage + " miles");
        System.out.println();
    }

    public void drive(int miles) {
        if (miles > 0) {
            mileage += miles;
            System.out.println("Drove " + miles + " miles. Total mileage: " + mileage);
        }
    }
}

// Class with private constructor (Singleton pattern)
class DatabaseConnection {
    private static DatabaseConnection instance;
    private String connectionString;

    // Private constructor - cannot be called from outside
    private DatabaseConnection() {
        connectionString = "jdbc:mysql://localhost:3306/mydatabase";
        System.out.println("Database connection created");
    }

    // Public method to get the single instance
    public static DatabaseConnection getInstance() {
        if (instance == null) {
            instance = new DatabaseConnection();
        }
        return instance;
    }

    public void connect() {
        System.out.println("Connected to: " + connectionString);
    }
}

public class ConstructorsDemo {
    public static void main(String[] args) {
        System.out.println("=== Constructors Demonstration ===\n");

        // Using different constructors
        System.out.println("=== Person Class Constructors ===");

        Person person1 = new Person();  // Default constructor
        person1.displayInfo();

        Person person2 = new Person("Alice Johnson", 25);  // 2-parameter constructor
        person2.displayInfo();

        Person person3 = new Person("Bob Smith", 30, "bob.smith@email.com");  // 3-parameter constructor
        person3.displayInfo();

        // Using copy constructor
        Person person4 = new Person(person3);  // Copy of person3
        person4.displayInfo();

        // Modifying copy to show they're separate
        person4.name = "Charlie Brown";
        System.out.println("After modifying copy:");
        System.out.println("Original: " + person3.name);
        System.out.println("Copy: " + person4.name);

        System.out.println("\n=== Car Class Constructors ===");

        // Car with full parameters
        Car car1 = new Car("Toyota", "Camry", 2023, 25000.0);
        car1.displayCarInfo();

        // Car with invalid parameters (testing validation)
        Car car2 = new Car("Honda", "Civic", 1800, -10000.0);
        car2.displayCarInfo();

        // Car with chained constructor
        Car car3 = new Car("Ford", "Mustang");
        car3.displayCarInfo();

        // Default car
        Car car4 = new Car();
        car4.displayCarInfo();

        // Using car methods
        car1.drive(150);
        car1.drive(75);
        car1.displayCarInfo();

        System.out.println("\n=== Singleton Pattern (Private Constructor) ===");

        // Cannot do this: DatabaseConnection db = new DatabaseConnection();
        // Constructor is private

        DatabaseConnection db1 = DatabaseConnection.getInstance();
        db1.connect();

        DatabaseConnection db2 = DatabaseConnection.getInstance();
        db2.connect();

        // Both references point to same object
        System.out.println("db1 == db2: " + (db1 == db2));

        System.out.println("\n=== Constructor Best Practices ===");

        // Array of objects with different constructors
        Person[] people = new Person[4];
        people[0] = new Person();
        people[1] = new Person("John Doe", 28);
        people[2] = new Person("Jane Smith", 32, "jane.smith@company.com");
        people[3] = new Person(people[1]);  // Copy

        System.out.println("People array:");
        for (Person person : people) {
            person.displayInfo();
        }

        // Constructor with 'this' keyword
        System.out.println("=== Using 'this' Keyword ===");

        Person person5 = new Person("David Wilson", 40, "david@test.com");
        person5.displayInfo();
    }
}

// Additional example showing 'this' keyword usage
class Student {
    String name;
    int age;

    // Using 'this' to distinguish between instance variables and parameters
    public Student(String name, int age) {
        this.name = name;  // this.name refers to instance variable
        this.age = age;    // age refers to parameter
    }

    // Method using 'this' to call another constructor
    public Student(String name) {
        this(name, 0);  // Calls the main constructor
    }

    public void display() {
        System.out.println("Student: " + this.name + ", Age: " + this.age);
    }
}

// Demonstrating inheritance in Java

// Parent class (Superclass)
class Animal {
    // Protected access - accessible in subclasses
    protected String name;
    protected int age;
    protected String sound;

    // Constructor
    public Animal(String name, int age, String sound) {
        this.name = name;
        this.age = age;
        this.sound = sound;
    }

    // Default constructor
    public Animal() {
        this("Unknown Animal", 0, "...");
    }

    // Methods
    public void makeSound() {
        System.out.println(name + " says: " + sound);
    }

    public void eat() {
        System.out.println(name + " is eating...");
    }

    public void sleep() {
        System.out.println(name + " is sleeping...");
    }

    public void displayInfo() {
        System.out.println("Animal: " + name);
        System.out.println("Age: " + age + " years");
        System.out.println("Sound: " + sound);
    }
}

// Child class 1 (Subclass of Animal)
class Dog extends Animal {
    private String breed;
    private boolean isTrained;

    // Constructor
    public Dog(String name, int age, String breed, boolean isTrained) {
        // Call parent constructor using super()
        super(name, age, "Woof!");
        this.breed = breed;
        this.isTrained = isTrained;
    }

    // Default constructor
    public Dog() {
        super();  // Call default parent constructor
        this.breed = "Unknown";
        this.isTrained = false;
    }

    // Additional methods specific to Dog
    public void bark() {
        System.out.println(name + " is barking loudly!");
    }

    public void fetch() {
        System.out.println(name + " is fetching the ball!");
    }

    // Override parent method
    @Override
    public void displayInfo() {
        super.displayInfo();  // Call parent method
        System.out.println("Breed: " + breed);
        System.out.println("Trained: " + (isTrained ? "Yes" : "No"));
    }

    // Getters and setters
    public String getBreed() {
        return breed;
    }

    public void setBreed(String breed) {
        this.breed = breed;
    }

    public boolean isTrained() {
        return isTrained;
    }

    public void setTrained(boolean trained) {
        isTrained = trained;
    }
}

// Child class 2 (Subclass of Animal)
class Cat extends Animal {
    private String color;
    private boolean isIndoor;

    public Cat(String name, int age, String color, boolean isIndoor) {
        super(name, age, "Meow!");
        this.color = color;
        this.isIndoor = isIndoor;
    }

    // Additional methods specific to Cat
    public void purr() {
        System.out.println(name + " is purring...");
    }

    public void climb() {
        System.out.println(name + " is climbing a tree!");
    }

    // Override parent method
    @Override
    public void makeSound() {
        System.out.println(name + " purrs and says: " + sound);
    }

    @Override
    public void displayInfo() {
        super.displayInfo();
        System.out.println("Color: " + color);
        System.out.println("Indoor cat: " + (isIndoor ? "Yes" : "No"));
    }
}

// Multi-level inheritance
class Puppy extends Dog {
    private int monthsOld;

    public Puppy(String name, int months, String breed) {
        super(name, 0, breed, false);  // Puppies are 0 years old, not trained
        this.monthsOld = months;
        this.sound = "Yip!";  // Puppies have different sound
    }

    @Override
    public void displayInfo() {
        System.out.println("Puppy: " + name);
        System.out.println("Age: " + monthsOld + " months");
        System.out.println("Breed: " + getBreed());
        System.out.println("Sound: " + sound);
    }

    public void play() {
        System.out.println(name + " is playing happily!");
    }
}

// Another inheritance example: Vehicles
class Vehicle {
    protected String brand;
    protected int year;
    protected double speed;

    public Vehicle(String brand, int year) {
        this.brand = brand;
        this.year = year;
        this.speed = 0;
    }

    public void accelerate(double amount) {
        speed += amount;
        System.out.println(brand + " accelerating to " + speed + " mph");
    }

    public void brake(double amount) {
        speed = Math.max(0, speed - amount);
        System.out.println(brand + " slowing down to " + speed + " mph");
    }

    public void displayInfo() {
        System.out.println(year + " " + brand);
        System.out.println("Current speed: " + speed + " mph");
    }
}

class Car extends Vehicle {
    private int doors;
    private String fuelType;

    public Car(String brand, int year, int doors, String fuelType) {
        super(brand, year);
        this.doors = doors;
        this.fuelType = fuelType;
    }

    public void honk() {
        System.out.println(brand + " goes Beep Beep!");
    }

    @Override
    public void displayInfo() {
        super.displayInfo();
        System.out.println("Doors: " + doors);
        System.out.println("Fuel: " + fuelType);
    }
}

class Bicycle extends Vehicle {
    private int gears;

    public Bicycle(String brand, int year, int gears) {
        super(brand, year);
        this.gears = gears;
    }

    public void ringBell() {
        System.out.println(brand + " bicycle rings its bell!");
    }

    @Override
    public void accelerate(double amount) {
        // Bicycles accelerate slower
        speed += amount * 0.5;
        System.out.println(brand + " bicycle pedaling to " + speed + " mph");
    }

    @Override
    public void displayInfo() {
        super.displayInfo();
        System.out.println("Gears: " + gears);
    }
}

public class InheritanceDemo {
    public static void main(String[] args) {
        System.out.println("=== Inheritance Demonstration ===\n");

        System.out.println("=== Animal Inheritance Hierarchy ===");

        // Create parent class object
        Animal genericAnimal = new Animal("Generic", 5, "...");
        genericAnimal.displayInfo();
        genericAnimal.makeSound();

        System.out.println("\n--- Dog (Child Class) ---");

        // Create child class objects
        Dog myDog = new Dog("Buddy", 3, "Golden Retriever", true);
        myDog.displayInfo();  // Inherited method
        myDog.makeSound();    // Inherited method
        myDog.bark();         // Dog-specific method
        myDog.fetch();        // Dog-specific method
        myDog.eat();          // Inherited from Animal

        System.out.println("\n--- Cat (Child Class) ---");

        Cat myCat = new Cat("Whiskers", 2, "Gray", true);
        myCat.displayInfo();
        myCat.makeSound();    // Overridden method
        myCat.purr();         // Cat-specific method
        myCat.climb();        // Cat-specific method

        System.out.println("\n--- Multi-level Inheritance (Puppy) ---");

        Puppy myPuppy = new Puppy("Max", 6, "Labrador");
        myPuppy.displayInfo();
        myPuppy.makeSound();  // Inherited from Animal
        myPuppy.bark();       // Inherited from Dog
        myPuppy.play();       // Puppy-specific method

        System.out.println("\n=== Vehicle Inheritance Hierarchy ===");

        Car myCar = new Car("Toyota", 2023, 4, "Gasoline");
        myCar.displayInfo();
        myCar.accelerate(30);
        myCar.honk();
        myCar.brake(10);

        System.out.println("\n---");

        Bicycle myBike = new Bicycle("Trek", 2022, 21);
        myBike.displayInfo();
        myBike.accelerate(10);  // Overridden method
        myBike.ringBell();

        System.out.println("\n=== Polymorphism with Inheritance ===");

        // Array of parent type holding different child objects
        Animal[] animals = new Animal[3];
        animals[0] = new Dog("Rex", 4, "German Shepherd", true);
        animals[1] = new Cat("Mittens", 1, "White", false);
        animals[2] = new Animal("Bird", 2, "Chirp!");

        System.out.println("Animal sounds:");
        for (Animal animal : animals) {
            animal.makeSound();  // Polymorphism - each calls its own version
        }

        System.out.println("\n=== instanceof Operator ===");

        // Check object types
        for (Animal animal : animals) {
            System.out.print(animal.name + " is: ");
            if (animal instanceof Dog) {
                System.out.println("a Dog");
            } else if (animal instanceof Cat) {
                System.out.println("a Cat");
            } else {
                System.out.println("an Animal");
            }
        }

        System.out.println("\n=== Method Overriding Demonstration ===");

        // Show how overridden methods work
        Animal dogAsAnimal = new Dog("Spot", 2, "Beagle", false);
        dogAsAnimal.makeSound();  // Calls Dog's overridden version
        dogAsAnimal.displayInfo(); // Calls Dog's overridden version
    }
}

// Demonstrating polymorphism in Java

// Base class
class Shape {
    protected String color;

    public Shape(String color) {
        this.color = color;
    }

    // This method will be overridden by subclasses
    public double calculateArea() {
        System.out.println("Calculating area for generic shape");
        return 0.0;
    }

    public void displayInfo() {
        System.out.println("Shape color: " + color);
    }

    // A method that won't be overridden
    public final void setColor(String color) {
        this.color = color;
        System.out.println("Shape color changed to: " + color);
    }
}

// Subclass 1
class Circle extends Shape {
    private double radius;

    public Circle(String color, double radius) {
        super(color);
        this.radius = radius;
    }

    // Override calculateArea method
    @Override
    public double calculateArea() {
        return Math.PI * radius * radius;
    }

    @Override
    public void displayInfo() {
        System.out.println("Circle - Color: " + color + ", Radius: " + radius);
        System.out.println("Area: " + calculateArea());
    }

    // Circle-specific method
    public double calculateCircumference() {
        return 2 * Math.PI * radius;
    }
}

// Subclass 2
class Rectangle extends Shape {
    private double length;
    private double width;

    public Rectangle(String color, double length, double width) {
        super(color);
        this.length = length;
        this.width = width;
    }

    // Override calculateArea method
    @Override
    public double calculateArea() {
        return length * width;
    }

    @Override
    public void displayInfo() {
        System.out.println("Rectangle - Color: " + color + ", Length: " + length + ", Width: " + width);
        System.out.println("Area: " + calculateArea());
    }

    // Rectangle-specific method
    public double calculatePerimeter() {
        return 2 * (length + width);
    }
}

// Subclass 3
class Triangle extends Shape {
    private double base;
    private double height;

    public Triangle(String color, double base, double height) {
        super(color);
        this.base = base;
        this.height = height;
    }

    // Override calculateArea method
    @Override
    public double calculateArea() {
        return 0.5 * base * height;
    }

    @Override
    public void displayInfo() {
        System.out.println("Triangle - Color: " + color + ", Base: " + base + ", Height: " + height);
        System.out.println("Area: " + calculateArea());
    }
}

// Interface for polymorphism
interface Payment {
    void processPayment(double amount);
    boolean validatePayment();
    default void receipt() {
        System.out.println("Payment processed successfully!");
    }
}

// Classes implementing Payment interface
class CreditCardPayment implements Payment {
    private String cardNumber;
    private String cardHolder;

    public CreditCardPayment(String cardNumber, String cardHolder) {
        this.cardNumber = cardNumber;
        this.cardHolder = cardHolder;
    }

    @Override
    public void processPayment(double amount) {
        System.out.println("Processing credit card payment of $" + amount);
        System.out.println("Card: " + cardNumber + " (" + cardHolder + ")");
    }

    @Override
    public boolean validatePayment() {
        System.out.println("Validating credit card...");
        return cardNumber != null && cardNumber.length() == 16;
    }
}

class PayPalPayment implements Payment {
    private String email;

    public PayPalPayment(String email) {
        this.email = email;
    }

    @Override
    public void processPayment(double amount) {
        System.out.println("Processing PayPal payment of $" + amount);
        System.out.println("Email: " + email);
    }

    @Override
    public boolean validatePayment() {
        System.out.println("Validating PayPal account...");
        return email != null && email.contains("@");
    }

    @Override
    public void receipt() {
        System.out.println("PayPal payment completed! Check your email for receipt.");
    }
}

class BankTransferPayment implements Payment {
    private String accountNumber;
    private String bankName;

    public BankTransferPayment(String accountNumber, String bankName) {
        this.accountNumber = accountNumber;
        this.bankName = bankName;
    }

    @Override
    public void processPayment(double amount) {
        System.out.println("Processing bank transfer of $" + amount);
        System.out.println("Bank: " + bankName + ", Account: " + accountNumber);
    }

    @Override
    public boolean validatePayment() {
        System.out.println("Validating bank account...");
        return accountNumber != null && !accountNumber.isEmpty();
    }
}

// Abstract class example
abstract class Animal {
    protected String name;

    public Animal(String name) {
        this.name = name;
    }

    // Abstract method - must be implemented by subclasses
    public abstract void makeSound();

    // Concrete method
    public void sleep() {
