public class PolymorphismDemo {
    public static void main(String[] args) {
        System.out.println("=== Polymorphism Demonstration ===\n");

        System.out.println("=== Shape Polymorphism ===");

        // Creating different shapes but storing as Shape type
        Shape[] shapes = new Shape[3];
        shapes[0] = new Circle("Red", 5.0);
        shapes[1] = new Rectangle("Blue", 4.0, 6.0);
        shapes[2] = new Triangle("Green", 3.0, 4.0);

        // Polymorphic behavior - same method call, different results
        System.out.println("Calculating areas polymorphically:");
        for (Shape shape : shapes) {
            shape.displayInfo();  // Each calls its own version
            System.out.println();
        }

        // Calculate total area
        double totalArea = 0;
        for (Shape shape : shapes) {
            totalArea += shape.calculateArea();
        }
        System.out.println("Total area of all shapes: " + totalArea);

        System.out.println("\n=== Accessing Subclass-specific Methods ===");

        // To access subclass methods, we need to check type and cast
        for (Shape shape : shapes) {
            if (shape instanceof Circle) {
                Circle circle = (Circle) shape;  // Downcasting
                System.out.println("Circle circumference: " + circle.calculateCircumference());
            } else if (shape instanceof Rectangle) {
                Rectangle rectangle = (Rectangle) shape;
                System.out.println("Rectangle perimeter: " + rectangle.calculatePerimeter());
            }
        }

        System.out.println("\n=== Interface Polymorphism ===");

        // Different payment methods treated as Payment interface
        Payment[] payments = new Payment[3];
        payments[0] = new CreditCardPayment("1234567812345678", "John Doe");
        payments[1] = new PayPalPayment("user@example.com");
        payments[2] = new BankTransferPayment("ACC789012", "City Bank");

        double amount = 100.0;

        System.out.println("Processing payments polymorphically:");
        for (Payment payment : payments) {
            if (payment.validatePayment()) {
                payment.processPayment(amount);
                payment.receipt();
            } else {
                System.out.println("Payment validation failed!");
            }
            System.out.println();
        }

        System.out.println("=== Abstract Class Polymorphism ===");

        // Animals treated as Animal type but behave differently
        Animal[] animals = new Animal[3];
        animals[0] = new Dog("Buddy");
        animals[1] = new Cat("Whiskers");
        animals[2] = new Cow("Bessie");

        System.out.println("Animal sounds (polymorphism):");
        for (Animal animal : animals) {
            animal.makeSound();  // Each calls its own implementation
        }

        System.out.println("\nCommon behavior:");
        for (Animal animal : animals) {
            animal.eat();  // Inherited concrete method
        }

        System.out.println("\n=== Runtime Polymorphism (Dynamic Binding) ===");

        // The actual method called is determined at runtime
        Shape shape;

        // At compile time, shape is Shape type
        // At runtime, it can be any subclass
        shape = new Circle("Yellow", 7.0);
        shape.displayInfo();  // Calls Circle's displayInfo

        shape = new Rectangle("Purple", 5.0, 3.0);
        shape.displayInfo();  // Calls Rectangle's displayInfo

        System.out.println("\n=== Method Overloading vs Overriding ===");

        // Method overloading (compile-time polymorphism)
        Calculator calc = new Calculator();
        System.out.println("Add integers: " + calc.add(5, 3));
        System.out.println("Add doubles: " + calc.add(5.5, 3.2));
        System.out.println("Add three numbers: " + calc.add(1, 2, 3));
    }
}

