// Demonstrating encapsulation in Java

// Fully encapsulated class
class BankAccount {
    // Private data members - cannot be accessed directly from outside
    private String accountNumber;
    private String accountHolder;
    private double balance;
    private String accountType;
    private boolean isActive;

    // Constructor
    public BankAccount(String accountNumber, String accountHolder, double initialBalance, String accountType) {
        this.accountNumber = accountNumber;
        this.accountHolder = accountHolder;
        this.balance = Math.max(0, initialBalance); // Ensure non-negative balance
        this.accountType = accountType;
        this.isActive = true;
    }

    // Public getter methods - provide read access
    public String getAccountNumber() {
        return accountNumber;
    }

    public String getAccountHolder() {
        return accountHolder;
    }

    public double getBalance() {
        return balance;
    }

    public String getAccountType() {
        return accountType;
    }

    public boolean isActive() {
        return isActive;
    }

    // Public setter methods - provide controlled write access
    public void setAccountHolder(String accountHolder) {
        if (accountHolder != null && !accountHolder.trim().isEmpty()) {
            this.accountHolder = accountHolder;
            System.out.println("Account holder name updated to: " + accountHolder);
        } else {
            System.out.println("Invalid account holder name!");
        }
    }

    public void setAccountType(String accountType) {
        if (accountType.equals("Savings") || accountType.equals("Checking") || accountType.equals("Business")) {
            this.accountType = accountType;
            System.out.println("Account type updated to: " + accountType);
        } else {
            System.out.println("Invalid account type! Must be Savings, Checking, or Business");
        }
    }

    // No setter for accountNumber - cannot be changed after creation
    // No setter for balance - can only be modified through deposit/withdraw methods

    // Business methods that manipulate the private data
    public void deposit(double amount) {
        if (!isActive) {
            System.out.println("Cannot deposit: Account is inactive!");
            return;
        }

        if (amount > 0) {
            balance += amount;
            System.out.println("Deposited: $" + amount);
            System.out.println("New balance: $" + balance);
        } else {
            System.out.println("Deposit amount must be positive!");
        }
    }

    public void withdraw(double amount) {
        if (!isActive) {
            System.out.println("Cannot withdraw: Account is inactive!");
            return;
        }

        if (amount > 0) {
            if (amount <= balance) {
                balance -= amount;
                System.out.println("Withdrawn: $" + amount);
                System.out.println("New balance: $" + balance);
            } else {
                System.out.println("Insufficient funds! Current balance: $" + balance);
            }
        } else {
            System.out.println("Withdrawal amount must be positive!");
        }
    }

    public void transfer(BankAccount recipient, double amount) {
        if (!isActive || !recipient.isActive) {
            System.out.println("Transfer failed: One or both accounts are inactive!");
            return;
        }

        if (amount > 0 && amount <= balance) {
            this.balance -= amount;
            recipient.balance += amount;
            System.out.println("Transferred: $" + amount + " to " + recipient.getAccountHolder());
            System.out.println("Your new balance: $" + balance);
        } else if (amount > balance) {
            System.out.println("Transfer failed: Insufficient funds!");
        } else {
            System.out.println("Transfer amount must be positive!");
        }
    }

    // Administrative methods
    public void activateAccount() {
        isActive = true;
        System.out.println("Account activated successfully!");
    }

    public void deactivateAccount() {
        isActive = false;
        System.out.println("Account deactivated successfully!");
    }

    // Display account information (controlled access)
    public void displayAccountInfo() {
        System.out.println("=== Account Information ===");
        System.out.println("Account Number: " + accountNumber);
        System.out.println("Account Holder: " + accountHolder);
        System.out.println("Account Type: " + accountType);
        System.out.println("Balance: $" + balance);
        System.out.println("Status: " + (isActive ? "Active" : "Inactive"));
    }

    // Private helper method - internal use only
    private boolean isValidTransaction(double amount) {
        return amount > 0 && isActive;
    }
}

// Another encapsulated class example
class Student {
    private String studentId;
    private String name;
    private int age;
    private double gpa;
    private String[] courses;

    public Student(String studentId, String name, int age) {
        this.studentId = studentId;
        this.name = name;
        this.age = Math.max(0, age); // Age cannot be negative
        this.gpa = 0.0;
        this.courses = new String[0];
    }

    // Getters
    public String getStudentId() {
        return studentId;
    }

    public String getName() {
        return name;
    }

    public int getAge() {
        return age;
    }

    public double getGpa() {
        return gpa;
    }

    public String[] getCourses() {
        // Return a copy to protect the original array
        return courses.clone();
    }

    // Setters with validation
    public void setName(String name) {
        if (name != null && name.matches("[a-zA-Z\\s]+")) {
            this.name = name;
        } else {
            System.out.println("Invalid name! Only letters and spaces allowed.");
        }
    }

    public void setAge(int age) {
        if (age >= 0 && age <= 120) {
            this.age = age;
        } else {
            System.out.println("Invalid age! Must be between 0 and 120.");
        }
    }

    // No setter for studentId - immutable
    // No direct setter for GPA - calculated from grades

    // Business methods
    public void addCourse(String course) {
        if (course == null || course.trim().isEmpty()) {
            System.out.println("Invalid course name!");
            return;
        }

        // Check if course already exists
        for (String existingCourse : courses) {
            if (existingCourse.equals(course)) {
                System.out.println("Course '" + course + "' already exists!");
                return;
            }
        }

        // Add new course
        String[] newCourses = new String[courses.length + 1];
        System.arraycopy(courses, 0, newCourses, 0, courses.length);
        newCourses[courses.length] = course;
        courses = newCourses;

        System.out.println("Course '" + course + "' added successfully!");
    }

    public void removeCourse(String course) {
        if (course == null) {
            System.out.println("Invalid course name!");
            return;
        }

        int index = -1;
        for (int i = 0; i < courses.length; i++) {
            if (courses[i].equals(course)) {
                index = i;
                break;
            }
        }

        if (index == -1) {
            System.out.println("Course '" + course + "' not found!");
            return;
        }

        // Remove course
        String[] newCourses = new String[courses.length - 1];
        for (int i = 0, j = 0; i < courses.length; i++) {
            if (i != index) {
                newCourses[j++] = courses[i];
            }
        }
        courses = newCourses;

        System.out.println("Course '" + course + "' removed successfully!");
    }

    public void updateGPA(double newGPA) {
        if (newGPA >= 0.0 && newGPA <= 4.0) {
            this.gpa = newGPA;
            System.out.println(name + "'s GPA updated to: " + gpa);
        } else {
            System.out.println("Invalid GPA! Must be between 0.0 and 4.0");
        }
    }

    public void displayStudentInfo() {
        System.out.println("=== Student Information ===");
        System.out.println("Student ID: " + studentId);
        System.out.println("Name: " + name);
        System.out.println("Age: " + age);
        System.out.println("GPA: " + gpa);
        System.out.println("Courses: " + String.join(", ", courses));
    }

    // Private helper method
    private boolean isValidCourse(String course) {
        return course != null && !course.trim().isEmpty();
    }
}

