        System.out.println("=== Bank Account Example ===");

        // Create bank account
        BankAccount account1 = new BankAccount("ACC123456", "Alice Johnson", 1000.0, "Savings");
        BankAccount account2 = new BankAccount("ACC789012", "Bob Smith", 500.0, "Checking");

