        // Try to access private fields directly (this would cause compilation error)
        // System.out.println(account1.balance);  // Error: balance has private access
        // account1.balance = 5000;  // Error: balance has private access

        // Use public methods to interact with the object
        System.out.println("\n--- Performing Transactions ---");
        account1.deposit(250.0);
        account1.withdraw(100.0);
        account1.withdraw(2000.0);  // Should fail - insufficient funds

        // Transfer between accounts
        System.out.println("\n--- Transfer ---");
        account1.transfer(account2, 200.0);

        // Update account information using setters
        System.out.println("\n--- Updating Account Information ---");
        account1.setAccountHolder("Alice Smith");  // Valid change
        account1.setAccountType("Business");       // Valid change
        account1.setAccountType("InvalidType");    // Invalid - should be rejected

        // Display updated information
        System.out.println("\n--- Updated Account Information ---");
        account1.displayAccountInfo();
        account2.displayAccountInfo();

        // Account activation/deactivation
        System.out.println("\n--- Account Management ---");
        account1.deactivateAccount();
        account1.deposit(100.0);  // Should fail - account inactive
        account1.activateAccount();
        account1.deposit(100.0);  // Should work now

        System.out.println("\n=== Student Example ===");

        Student student1 = new Student("S1001", "John Doe", 20);

        // Use public methods to interact with student
        student1.displayStudentInfo();

        System.out.println("\n--- Managing Courses ---");
        student1.addCourse("Mathematics");
        student1.addCourse("Computer Science");
        student1.addCourse("Physics");
        student1.addCourse("Mathematics");  // Should fail - duplicate

        student1.displayStudentInfo();

        student1.removeCourse("Physics");
        student1.removeCourse("Chemistry");  // Should fail - not found

        student1.displayStudentInfo();

        System.out.println("\n--- Updating Student Information ---");
        student1.setName("John Smith");     // Valid
        student1.setName("John123");        // Invalid - should be rejected
        student1.setAge(21);                // Valid
        student1.setAge(150);               // Invalid - should be rejected
        student1.updateGPA(3.75);           // Valid
        student1.updateGPA(5.0);            // Invalid - should be rejected

        student1.displayStudentInfo();

        System.out.println("\n=== Benefits of Encapsulation ===");

        // 1. Data protection
        System.out.println("1. Data Protection:");
        System.out.println("   - Private fields prevent direct modification");
        System.out.println("   - Setters provide validation");

        // 2. Controlled access
        System.out.println("2. Controlled Access:");
        System.out.println("   - Getters provide read access");
        System.out.println("   - Business methods control how data is modified");

        // 3. Flexibility to change implementation
        System.out.println("3. Implementation Flexibility:");
        System.out.println("   - Internal implementation can change without affecting users");
        System.out.println("   - Example: courses array could be changed to ArrayList without affecting callers");

        // 4. Maintainability
        System.out.println("4. Maintainability:");
        System.out.println("   - Validation logic is centralized");
        System.out.println("   - Easy to add new features or constraints");
    }
}

