            System.out.println("Deposited: $" + amount + " to checking account");
        } else {
            System.out.println("Invalid deposit amount!");
        }
    }

    @Override
    public double calculateInterest() {
        System.out.println("Checking accounts typically don't earn interest");
        return 0.0;
    }

    public void writeCheck(double amount) {
        System.out.println("Check written for: $" + amount);
        withdraw(amount);
    }
}

public class AbstractionDemo {
    public static void main(String[] args) {
        System.out.println("=== Abstraction Demonstration ===\n");

        System.out.println("=== Abstract Class Example ===");

        // Cannot instantiate abstract class
        // Vehicle vehicle = new Vehicle("Generic", "Vehicle", 2023);  // Error!

        // But we can use abstract class references
        Vehicle car = new Car("Toyota", "Camry", 2023, 4);
        Vehicle motorcycle = new Motorcycle("Harley", "Davidson", 2022, false);

        // Polymorphic behavior
        Vehicle[] vehicles = {car, motorcycle};

        for (Vehicle vehicle : vehicles) {
            vehicle.displayInfo();
            vehicle.start();
            vehicle.accelerate();
            vehicle.honk();
            vehicle.stop();
            System.out.println();
        }

        // Accessing subclass-specific methods
        System.out.println("--- Subclass-specific Methods ---");
        Car myCar = (Car) car;
        myCar.openTrunk();

        Motorcycle myMotorcycle = (Motorcycle) motorcycle;
        myMotorcycle.wheelie();

        System.out.println("\n=== Interface Example ===");

        SmartSpeaker speaker = new SmartSpeaker("Amazon", "Echo");

        // Using interface methods
        speaker.displayType();  // Default method
        speaker.connectToWiFi("HomeNetwork");
        speaker.playMusic("Yesterday - The Beatles");
        speaker.adjustVolume(75);
        speaker.displayStatus();

        // Static interface method
        SmartDevice.showTechnology();

        System.out.println("\n--- Multiple Interfaces ---");

        // Treat as different interface types
        SmartDevice device = speaker;
        EntertainmentSystem entertainment = speaker;

        device.updateSoftware();
        entertainment.playMusic("Another Song");
        entertainment.emergencyAlert();  // Default method

        System.out.println("\n=== Bank Account Abstraction ===");

        BankAccount savings = new SavingsAccount("SAV123", "Alice", 5000.0, 2.5);
        BankAccount checking = new CheckingAccount("CHK456", "Bob", 1000.0, 500.0);

        BankAccount[] accounts = {savings, checking};

        for (BankAccount account : accounts) {
            account.displayAccountInfo();  // Final method - same for all
            account.deposit(500.0);
            account.withdraw(200.0);
            account.calculateInterest();   // Abstract method - different implementations
            System.out.println();
        }

        // Subclass-specific methods
        System.out.println("--- Account-specific Features ---");
        SavingsAccount savingsAcc = (SavingsAccount) savings;
        savingsAcc.addInterest();

        CheckingAccount checkingAcc = (CheckingAccount) checking;
        checkingAcc.writeCheck(300.0);

        System.out.println("\n=== Benefits of Abstraction ===");

        System.out.println("1. Simplifies Complex Systems:");
        System.out.println("   - Users don't need to know internal implementation");
        System.out.println("   - Focus on what objects do, not how they do it");

        System.out.println("2. Promotes Code Reuse:");
        System.out.println("   - Common functionality in abstract classes");
        System.out.println("   - Multiple implementations of same interface");

        System.out.println("3. Enables Polymorphism:");
        System.out.println("   - Treat different objects uniformly");
        System.out.println("   - Easy to extend with new types");

        System.out.println("4. Loose Coupling:");
        System.out.println("   - Depend on abstractions, not concrete implementations");
        System.out.println("   - Easy to swap implementations");
    }
}

