// Class with different access modifiers
class TestClass {
    // Public field - accessible from anywhere
    public String publicField = "I am public";

    // Protected field - accessible in package and subclasses
    protected String protectedField = "I am protected";

    // Package-private (default) field - accessible only in same package
    String packageField = "I am package-private";

    // Private field - accessible only in this class
    private String privateField = "I am private";

