        System.out.println("Private method called");
    }

    // Method to test access within same class
    public void testAccess() {
        System.out.println("=== Access within Same Class ===");

        // All access levels are accessible within the same class
        System.out.println(publicField);     // OK
        System.out.println(protectedField);  // OK
        System.out.println(packageField);    // OK
        System.out.println(privateField);    // OK

        publicMethod();      // OK
