// Example demonstrating practical use of access modifiers
class BankAccount {
    // Private fields - encapsulated data
    private String accountNumber;
    private String accountHolder;
    private double balance;
    private String accountType;

    // Protected field - accessible to subclasses
    protected double interestRate;

    // Package-private field - for internal bank operations
    String branchCode;

    // Public constant
    public static final String BANK_NAME = "Java Bank";

    // Constructor
    public BankAccount(String accountNumber, String accountHolder, double initialBalance, String accountType) {
        this.accountNumber = accountNumber;
        this.accountHolder = accountHolder;
        this.balance = Math.max(0, initialBalance);
        this.accountType = accountType;
        this.interestRate = 0.0;
        this.branchCode = "MAIN";
    }

    // Public methods - interface for users
    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            System.out.println("Deposited: $" + amount);
        } else {
            System.out.println("Invalid deposit amount!");
        }
    }

    public void withdraw(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
            System.out.println("Withdrawn: $" + amount);
        } else {
            System.out.println("Invalid withdrawal amount or insufficient funds!");
        }
    }

    public double getBalance() {
        return balance;
    }

    public String getAccountHolder() {
        return accountHolder;
    }

    // Protected method - for subclasses
    protected void setInterestRate(double rate) {
        if (rate >= 0) {
            this.interestRate = rate;
            System.out.println("Interest rate set to: " + rate + "%");
        }
    }

    // Package-private method - for internal bank operations
    void updateBranchCode(String newCode) {
        this.branchCode = newCode;
        System.out.println("Branch code updated to: " + newCode);
    }

    // Private method - internal helper
    private boolean isValidAmount(double amount) {
        return amount > 0;
    }

    // Public method using private helper
    public void displayAccountInfo() {
        System.out.println("=== " + BANK_NAME + " ===");
        System.out.println("Account: " + accountNumber);
        System.out.println("Holder: " + accountHolder);
        System.out.println("Type: " + accountType);
        System.out.println("Balance: $" + balance);
        System.out.println("Branch: " + branchCode);
    }
}

