// Demonstrating static members and final keyword

class MathUtils {
    // Static final constant - belongs to class, cannot be changed
    public static final double PI = 3.14159;
    public static final double E = 2.71828;

    // Static variable - shared by all instances
    private static int instanceCount = 0;

    // Instance variable - each object has its own copy
    private int objectId;

    // Static initializer block - runs when class is loaded
    static {
        System.out.println("MathUtils class loaded!");
        System.out.println("PI = " + PI + ", E = " + E);
    }

    // Constructor
    public MathUtils() {
        instanceCount++;  // Increment shared counter
        objectId = instanceCount;  // Assign unique ID
        System.out.println("MathUtils object #" + objectId + " created");
    }

    // Static method - can be called without creating object
    public static double calculateCircleArea(double radius) {
        return PI * radius * radius;
    }

    public static double calculateCircleCircumference(double radius) {
        return 2 * PI * radius;
    }

    public static int factorial(int n) {
        if (n <= 1) return 1;
        return n * factorial(n - 1);
    }

    // Static method to access static variable
    public static int getInstanceCount() {
        return instanceCount;
    }

    // Instance method
    public void displayInfo() {
        System.out.println("Object ID: " + objectId);
        System.out.println("Total instances created: " + instanceCount);
    }

    // Final instance method - cannot be overridden
    public final void cannotOverride() {
        System.out.println("This method cannot be overridden by subclasses!");
    }
}

