// Demonstrating interfaces in Java

// Basic interface
interface Drawable {
    // Constant (implicitly public static final)
    String TYPE = "Drawable Object";

    // Abstract method (implicitly public abstract)
    void draw();

    // Another abstract method
    double calculateArea();

    // Default method (Java 8+) - has implementation
    default void displayType() {
        System.out.println("This is a: " + TYPE);
    }

    // Static method (Java 8+)
    static void showDrawingTools() {
        System.out.println("Common drawing tools: Pencil, Brush, Pen");
    }
}

// Another interface
interface Resizable {
    void resize(double factor);
    void resize(double width, double height);

    default void doubleSize() {
        resize(2.0);
    }
}

// Interface extending another interface
interface Colored extends Drawable {
    String getColor();
    void setColor(String color);

    default void makeTransparent() {
        setColor("Transparent");
    }
}

// Class implementing single interface
class Circle implements Drawable {
    private double radius;

    public Circle(double radius) {
        this.radius = radius;
    }

    @Override
    public void draw() {
        System.out.println("Drawing a circle with radius " + radius);
    }

    @Override
    public double calculateArea() {
        return Math.PI * radius * radius;
    }

    // Can override default method
    @Override
    public void displayType() {
        System.out.println("This is a Circle - " + TYPE);
    }

    // Circle-specific method
    public double getCircumference() {
        return 2 * Math.PI * radius;
    }
}

// Class implementing multiple interfaces
class Rectangle implements Drawable, Resizable {
    private double width;
    private double height;

    public Rectangle(double width, double height) {
        this.width = width;
        this.height = height;
    }

    @Override
    public void draw() {
        System.out.println("Drawing a rectangle " + width + "x" + height);
    }

    @Override
    public double calculateArea() {
        return width * height;
    }

    @Override
    public void resize(double factor) {
        width *= factor;
        height *= factor;
        System.out.println("Resized to: " + width + "x" + height);
    }

    @Override
    public void resize(double width, double height) {
        this.width = width;
        this.height = height;
        System.out.println("Resized to: " + width + "x" + height);
    }

    public double getPerimeter() {
        return 2 * (width + height);
    }
}

