    private String cardNumber;
    private String cardHolder;

    public CreditCardPayment(String cardNumber, String cardHolder) {
        this.cardNumber = cardNumber;
        this.cardHolder = cardHolder;
    }

    @Override
    public void processPayment(double amount) {
        System.out.println("Processing credit card payment of $" + amount);
        System.out.println("Card: " + cardNumber + " (" + cardHolder + ")");
    }

    @Override
    public boolean validatePayment() {
        boolean isValid = cardNumber != null && cardNumber.length() == 16;
        System.out.println("Credit card validation: " + (isValid ? "PASS" : "FAIL"));
        return isValid;
    }

    @Override
    public void receipt() {
        System.out.println("Credit Card Payment - Transaction Complete!");
    }
}

class PayPalPayment implements Payment {
    private String email;

    public PayPalPayment(String email) {
        this.email = email;
    }

    @Override
    public void processPayment(double amount) {
        System.out.println("Processing PayPal payment of $" + amount);
        System.out.println("Email: " + email);
    }

    @Override
    public boolean validatePayment() {
        boolean isValid = email != null && email.contains("@");
        System.out.println("PayPal validation: " + (isValid ? "PASS" : "FAIL"));
        return isValid;
    }
}

// Real-world example: Vehicle system
interface Vehicle {
    void start();
    void stop();
    void accelerate();

    default void honk() {
        System.out.println("Beep Beep!");
    }

    static void showVehicleTypes() {
        System.out.println("Car, Motorcycle, Truck, Bus");
    }
}

interface ElectricVehicle extends Vehicle {
    void chargeBattery();
    int getBatteryLevel();

    @Override
    default void start() {
        System.out.println("Electric vehicle starting silently...");
    }
}

class ElectricCar implements ElectricVehicle {
    private int batteryLevel;

    public ElectricCar() {
        this.batteryLevel = 100;
    }

    @Override
    public void start() {
        System.out.println("Electric car powered on!");
    }

    @Override
    public void stop() {
        System.out.println("Electric car powered off!");
    }

    @Override
    public void accelerate() {
        if (batteryLevel > 0) {
            batteryLevel -= 5;
            System.out.println("Electric car accelerating silently! Battery: " + batteryLevel + "%");
        } else {
            System.out.println("Cannot accelerate: Low battery!");
        }
    }

    @Override
    public void chargeBattery() {
        batteryLevel = 100;
        System.out.println("Battery fully charged!");
    }

    @Override
    public int getBatteryLevel() {
        return batteryLevel;
    }
}

public class InterfacesDemo {
    public static void main(String[] args) {
        System.out.println("=== Interfaces Demonstration ===\n");

        System.out.println("=== Basic Interface Usage ===");

        // Using interface type references
        Drawable circle = new Circle(5.0);
        Drawable rectangle = new Rectangle(4.0, 6.0);

        circle.draw();
        System.out.println("Circle area: " + circle.calculateArea());
        circle.displayType();  // Default method

        rectangle.draw();
        System.out.println("Rectangle area: " + rectangle.calculateArea());

        // Static interface method
        Drawable.showDrawingTools();

        System.out.println("\n=== Multiple Interfaces ===");

        Rectangle rect = new Rectangle(3.0, 4.0);
        rect.draw();
        rect.resize(2.0);  // Double size
        rect.doubleSize();  // Default method

        System.out.println("\n=== Extended Interface ===");

        Colored coloredCircle = new ColoredCircle(3.0, "Red");
        coloredCircle.draw();
        coloredCircle.setColor("Blue");
        coloredCircle.makeTransparent();  // Default method from extended interface

        System.out.println("\n=== Real-world: Payment System ===");

        Payment.showSupportedPayments();

        Payment[] payments = {
            new CreditCardPayment("1234567812345678", "John Doe"),
            new PayPalPayment("user@example.com")
        };

        double amount = 100.0;
        for (Payment payment : payments) {
            if (payment.validatePayment()) {
                payment.processPayment(amount);
                payment.receipt();
            }
            System.out.println();
        }

        System.out.println("=== Real-world: Electric Vehicle ===");

        ElectricVehicle tesla = new ElectricCar();
        tesla.start();
        tesla.accelerate();
        tesla.accelerate();
        tesla.honk();
        System.out.println("Battery level: " + tesla.getBatteryLevel() + "%");
        tesla.chargeBattery();
        tesla.stop();

        System.out.println("\n=== Functional Interfaces and Lambdas ===");

        // Using functional interface with lambda expressions
        Calculator addition = (a, b) -> a + b;
        Calculator multiplication = (a, b) -> a * b;
        Calculator division = (a, b) -> b != 0 ? a / b : 0;

        System.out.println("5 + 3 = " + addition.calculate(5, 3));
        System.out.println("5 * 3 = " + multiplication.calculate(5, 3));
        System.out.println("10 / 2 = " + division.calculate(10, 2));

        // Using static factory method
        Calculator add = Calculator.createAddition();
        System.out.println("7 + 8 = " + add.calculate(7, 8));

        // Validator example
        Validator emailValidator = email -> email != null && email.contains("@");
        Validator lengthValidator = str -> str != null && str.length() >= 5;

        Validator combinedValidator = emailValidator.and(lengthValidator);

        System.out.println("\nEmail validation:");
        System.out.println("test@example.com: " + combinedValidator.isValid("test@example.com"));
        System.out.println("short: " + combinedValidator.isValid("short"));

        System.out.println("\n=== Interface Polymorphism ===");

        // Array of different types implementing same interface
        Drawable[] drawables = {
            new Circle(7.0),
            new Rectangle(5.0, 3.0),
            new ColoredCircle(4.0, "Green")
        };

        System.out.println("Drawing all shapes:");
        for (Drawable drawable : drawables) {
            drawable.draw();
            System.out.println("Area: " + drawable.calculateArea());
        }

        System.out.println("\n=== instanceof with Interfaces ===");

        for (Drawable drawable : drawables) {
            if (drawable instanceof Resizable) {
                System.out.println("This shape is resizable");
            }
            if (drawable instanceof Colored) {
                System.out.println("This shape is colored: " + ((Colored) drawable).getColor());
            }
        }

        System.out.println("\n=== Benefits of Interfaces ===");
        System.out.println("1. Multiple Inheritance: Classes can implement multiple interfaces");
        System.out.println("2. Loose Coupling: Depend on interfaces, not implementations");
        System.out.println("3. Polymorphism: Treat different objects uniformly");
        System.out.println("4. Testability: Easy to mock interfaces for testing");
        System.out.println("5. Extensibility: Easy to add new implementations");
    }
}

// Demonstrating Java Collections Framework
import java.util.*;

public class CollectionsDemo {
    public static void main(String[] args) {
        System.out.println("=== Java Collections Framework ===\n");

        System.out.println("=== ArrayList Demonstration ===\n");

        // ArrayList - dynamic array
        ArrayList<String> fruits = new ArrayList<>();

        // Adding elements
        fruits.add("Apple");
        fruits.add("Banana");
        fruits.add("Orange");
        fruits.add("Mango");
        fruits.add("Grape");

        System.out.println("Fruits: " + fruits);
        System.out.println("Size: " + fruits.size());
        System.out.println("First fruit: " + fruits.get(0));
        System.out.println("Contains 'Apple': " + fruits.contains("Apple"));

        // Modifying ArrayList
        fruits.set(1, "Blueberry");  // Replace Banana with Blueberry
        System.out.println("After modification: " + fruits);

        fruits.remove("Orange");  // Remove by object
        fruits.remove(2);         // Remove by index
        System.out.println("After removal: " + fruits);

        // Iterating through ArrayList
        System.out.println("\nIterating with for-each:");
        for (String fruit : fruits) {
            System.out.println(" - " + fruit);
        }

        System.out.println("\nIterating with iterator:");
        Iterator<String> iterator = fruits.iterator();
        while (iterator.hasNext()) {
            System.out.println(" * " + iterator.next());
        }

        // Sorting
        Collections.sort(fruits);
        System.out.println("\nSorted fruits: " + fruits);

        System.out.println("\n=== LinkedList Demonstration ===\n");

        // LinkedList - efficient for add/remove at ends
        LinkedList<Integer> numbers = new LinkedList<>();

        numbers.add(10);
        numbers.add(20);
        numbers.addFirst(5);   // Add at beginning
        numbers.addLast(30);   // Add at end

        System.out.println("Numbers: " + numbers);
        System.out.println("First: " + numbers.getFirst());
        System.out.println("Last: " + numbers.getLast());

        numbers.removeFirst();
        numbers.removeLast();
        System.out.println("After removing first and last: " + numbers);

        System.out.println("\n=== HashSet Demonstration ===\n");

        // HashSet - no duplicates, no order
        HashSet<String> uniqueNames = new HashSet<>();

        uniqueNames.add("John");
        uniqueNames.add("Jane");
        uniqueNames.add("John");  // Duplicate - won't be added
        uniqueNames.add("Bob");
        uniqueNames.add("Alice");

        System.out.println("Unique names: " + uniqueNames);
        System.out.println("Size: " + uniqueNames.size());
        System.out.println("Contains 'John': " + uniqueNames.contains("John"));

        // Iterating HashSet
        System.out.println("\nHashSet elements:");
        for (String name : uniqueNames) {
            System.out.println(" - " + name);
        }

        System.out.println("\n=== HashMap Demonstration ===\n");

        // HashMap - key-value pairs
        HashMap<String, Integer> studentGrades = new HashMap<>();

        // Adding key-value pairs
        studentGrades.put("Alice", 85);
        studentGrades.put("Bob", 92);
        studentGrades.put("Charlie", 78);
        studentGrades.put("Diana", 95);

        System.out.println("Student grades: " + studentGrades);
        System.out.println("Alice's grade: " + studentGrades.get("Alice"));
        System.out.println("Contains key 'Bob': " + studentGrades.containsKey("Bob"));
        System.out.println("Contains value 100: " + studentGrades.containsValue(100));

        // Updating values
        studentGrades.put("Charlie", 82);  // Update existing key
        System.out.println("After update: " + studentGrades);

        // Removing entry
        studentGrades.remove("Diana");
        System.out.println("After removal: " + studentGrades);

        // Iterating HashMap
        System.out.println("\nIterating HashMap:");
        for (String name : studentGrades.keySet()) {
            System.out.println(name + " : " + studentGrades.get(name));
        }

        System.out.println("\nEntry set iteration:");
        for (Map.Entry<String, Integer> entry : studentGrades.entrySet()) {
            System.out.println(entry.getKey() + " -> " + entry.getValue());
        }

        System.out.println("\n=== TreeSet Demonstration ===\n");

        // TreeSet - sorted set
        TreeSet<Integer> sortedNumbers = new TreeSet<>();

        sortedNumbers.add(50);
        sortedNumbers.add(20);
        sortedNumbers.add(80);
        sortedNumbers.add(10);
        sortedNumbers.add(30);

        System.out.println("Sorted numbers: " + sortedNumbers);
        System.out.println("First: " + sortedNumbers.first());
        System.out.println("Last: " + sortedNumbers.last());
        System.out.println("Numbers less than 30: " + sortedNumbers.headSet(30));
        System.out.println("Numbers greater than or equal to 30: " + sortedNumbers.tailSet(30));

        System.out.println("\n=== Stack and Queue Demonstration ===\n");

        // Stack - LIFO (Last In First Out)
        Stack<String> stack = new Stack<>();
        stack.push("First");
        stack.push("Second");
        stack.push("Third");

        System.out.println("Stack: " + stack);
        System.out.println("Top element: " + stack.peek());
        System.out.println("Popped: " + stack.pop());
        System.out.println("Stack after pop: " + stack);

        // Queue - FIFO (First In First Out)
        Queue<String> queue = new LinkedList<>();
        queue.offer("First");
        queue.offer("Second");
        queue.offer("Third");

        System.out.println("\nQueue: " + queue);
        System.out.println("Front element: " + queue.peek());
        System.out.println("Removed: " + queue.poll());
        System.out.println("Queue after removal: " + queue);

        System.out.println("\n=== Practical Examples ===\n");

        // Example 1: Student Management
        System.out.println("=== Student Management Example ===");

        HashMap<String, ArrayList<Integer>> studentScores = new HashMap<>();

        // Add students with their scores
        studentScores.put("Alice", new ArrayList<>(Arrays.asList(85, 92, 78)));
        studentScores.put("Bob", new ArrayList<>(Arrays.asList(76, 88, 90)));
        studentScores.put("Charlie", new ArrayList<>(Arrays.asList(92, 95, 87)));

        // Calculate and display averages
        for (String student : studentScores.keySet()) {
            ArrayList<Integer> scores = studentScores.get(student);
            double average = scores.stream().mapToInt(Integer::intValue).average().orElse(0.0);
            System.out.println(student + "'s average: " + String.format("%.2f", average));
        }

        // Example 2: Word Frequency Counter
        System.out.println("\n=== Word Frequency Counter ===");

        String text = "hello world hello java world programming java hello";
        String[] words = text.split(" ");

        HashMap<String, Integer> wordCount = new HashMap<>();

        for (String word : words) {
            wordCount.put(word, wordCount.getOrDefault(word, 0) + 1);
        }

        System.out.println("Word frequencies:");
        for (Map.Entry<String, Integer> entry : wordCount.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }

        // Example 3: Unique Values
        System.out.println("\n=== Unique Values Example ===");

        ArrayList<Integer> numbersWithDuplicates = new ArrayList<>(Arrays.asList(1, 2, 2, 3, 4, 4, 4, 5, 5));
        HashSet<Integer> uniqueNumbers = new HashSet<>(numbersWithDuplicates);

        System.out.println("Original list: " + numbersWithDuplicates);
        System.out.println("Unique numbers: " + uniqueNumbers);

        System.out.println("\n=== Collection Operations ===");

        // Collection utility methods
        ArrayList<Integer> list1 = new ArrayList<>(Arrays.asList(1, 2, 3, 4, 5));
        ArrayList<Integer> list2 = new ArrayList<>(Arrays.asList(4, 5, 6, 7, 8));

        System.out.println("List 1: " + list1);
        System.out.println("List 2: " + list2);

        // Union
        HashSet<Integer> union = new HashSet<>(list1);
        union.addAll(list2);
        System.out.println("Union: " + union);

        // Intersection
        HashSet<Integer> intersection = new HashSet<>(list1);
        intersection.retainAll(list2);
        System.out.println("Intersection: " + intersection);

        // Difference
        HashSet<Integer> difference = new HashSet<>(list1);
        difference.removeAll(list2);
        System.out.println("Difference (list1 - list2): " + difference);

        System.out.println("\n=== Choosing the Right Collection ===");
        System.out.println("• ArrayList: When you need fast random access");
        System.out.println("• LinkedList: When you need frequent add/remove at ends");
        System.out.println("• HashSet: When you need unique elements, no order");
        System.out.println("• TreeSet: When you need unique elements, sorted");
        System.out.println("• HashMap: When you need key-value pairs, fast lookup");
        System.out.println("• TreeMap: When you need sorted key-value pairs");
        System.out.println("• Stack: When you need LIFO behavior");
        System.out.println("• Queue: When you need FIFO behavior");
    }
}
